'use strict';

const ESCAPE_MAP = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&apos;',
};

function xmlEscape(value) {
  return String(value).replace(/[&<>"']/g, (ch) => ESCAPE_MAP[ch]);
}

/**
 * Join origin and path without producing double slashes:
 * - strips trailing slashes from origin
 * - ensures exactly one slash between origin and path
 */
function joinUrl(origin, path) {
  const cleanOrigin = String(origin).replace(/\/+$/, '');
  const cleanPath = String(path).replace(/^\/+/, '');
  if (cleanPath === '') return cleanOrigin + '/';
  return `${cleanOrigin}/${cleanPath}`;
}

/**
 * Format a Date or date-like value as an ISO 8601 date (YYYY-MM-DD).
 * Strings that are already ISO are normalized to the date portion.
 */
function toIsoDate(lastmod) {
  if (lastmod instanceof Date) {
    return lastmod.toISOString().slice(0, 10);
  }
  const parsed = new Date(lastmod);
  if (Number.isNaN(parsed.getTime())) {
    throw new TypeError(`Invalid lastmod for sitemap entry: ${lastmod}`);
  }
  return parsed.toISOString().slice(0, 10);
}

/**
 * Build a valid sitemaps.org XML sitemap from a list of pages.
 *
 * @param {Array<{path: string, lastmod?: string|Date, changefreq?: string, priority?: number|string}>} pages
 * @param {string} origin - e.g. "https://example.com"
 * @returns {string} XML document
 */
function buildSitemap(pages, origin) {
  const entries = (pages || [])
    .map((page) => {
      const loc = xmlEscape(joinUrl(origin, page.path));
      const lines = ['  <url>', `    <loc>${loc}</loc>`];
      if (page.lastmod !== undefined && page.lastmod !== null && page.lastmod !== '') {
        lines.push(`    <lastmod>${toIsoDate(page.lastmod)}</lastmod>`);
      }
      if (page.changefreq !== undefined && page.changefreq !== null && page.changefreq !== '') {
        lines.push(`    <changefreq>${xmlEscape(page.changefreq)}</changefreq>`);
      }
      if (page.priority !== undefined && page.priority !== null && page.priority !== '') {
        const num = Number(page.priority);
        if (Number.isNaN(num)) {
          throw new TypeError(`Invalid priority for ${page.path}: ${page.priority}`);
        }
        // Always one decimal place: "1" -> "1.0", 0.75 -> "0.8"? No — keep exact value.
        lines.push(`    <priority>${num.toFixed(1)}</priority>`);
      }
      lines.push('  </url>');
      return lines.join('\n');
    })
    .join('\n');

  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    entries,
    '</urlset>',
    '',
  ]
    .filter((line) => line !== '' || true)
    .join('\n');
}

/**
 * Build robots.txt content.
 *
 * @param {{sitemapUrl: string, disallow?: string[]}} opts
 *   disallow: array of paths; empty/missing array emits a single "Disallow:" (allow all)
 * @returns {string}
 */
function buildRobots({ sitemapUrl, disallow = [] }) {
  const lines = ['User-agent: *'];
  const rules = disallow.length > 0 ? disallow : [''];
  for (const rule of rules) {
    lines.push(`Disallow: ${rule}`);
  }
  lines.push(`Sitemap: ${sitemapUrl}`);
  return lines.join('\n') + '\n';
}

module.exports = { buildSitemap, buildRobots, joinUrl, xmlEscape };

