'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { XMLParser } = require('fast-xml-parser');

const { buildSitemap, buildRobots, joinUrl } = require('../src/index.js');

const parser = new XMLParser({ ignoreAttributes: false });

test('buildSitemap produces valid XML with sitemaps.org namespace and correct entry count', () => {
  const pages = [
    { path: '/', lastmod: '2026-01-15', changefreq: 'weekly', priority: 1 },
    { path: '/about', lastmod: '2026-02-03T10:30:00Z', changefreq: 'monthly', priority: 0.8 },
    { path: '/blog/post-1', lastmod: '2026-03-20', changefreq: 'daily', priority: 0.5 },
  ];
  const xml = buildSitemap(pages, 'https://example.com');
  const doc = parser.parse(xml);

  assert.equal(doc.urlset['@_xmlns'], 'http://www.sitemaps.org/schemas/sitemap/0.9');

  const urls = Array.isArray(doc.urlset.url) ? doc.urlset.url : [doc.urlset.url];
  assert.equal(urls.length, 3);

  assert.equal(urls[0].loc, 'https://example.com/');
  assert.equal(urls[1].loc, 'https://example.com/about');
  assert.equal(urls[2].loc, 'https://example.com/blog/post-1');

  // ISO date lastmod
  assert.equal(urls[0].lastmod, '2026-01-15');
  assert.equal(urls[1].lastmod, '2026-02-03'); // datetime truncated to date
});

test('buildSitemap formats priorities with exactly one decimal', () => {
  const pages = [
    { path: '/', lastmod: '2026-01-01', priority: 1 },
    { path: '/half', lastmod: '2026-01-01', priority: 0.5 },
    { path: '/low', lastmod: '2026-01-01', priority: 0.25 },
  ];
  const xml = buildSitemap(pages, 'https://example.com');
  assert.match(xml, /<priority>1\.0<\/priority>/);
  assert.match(xml, /<priority>0\.5<\/priority>/);
  assert.match(xml, /<priority>0\.3<\/priority>/); // 0.25 -> one decimal

  const urls = parser.parse(xml).urlset.url;
  for (const u of urls) {
    assert.match(String(u.priority), /^\d\.\d$/);
  }
});

test('buildSitemap XML-escapes special characters in URLs (ampersand test)', () => {
  const pages = [{ path: '/search?q=seo&amp;lang=en', lastmod: '2026-04-01' }];
  const xml = buildSitemap(pages, 'https://example.com');

  // Raw XML must contain the escaped form
  assert.ok(xml.includes('<loc>https://example.com/search?q=seo&amp;amp;lang=en</loc>'));

  // Round-trip through the parser recovers the original value
  const url = parser.parse(xml).urlset.url;
  assert.equal(url.loc, 'https://example.com/search?q=seo&amp;lang=en');
});

test('joinUrl never produces double slashes', () => {
  assert.equal(joinUrl('https://example.com', '/a'), 'https://example.com/a');
  assert.equal(joinUrl('https://example.com/', '/a'), 'https://example.com/a');
  assert.equal(joinUrl('https://example.com//', '//a'), 'https://example.com/a');
  assert.equal(joinUrl('https://example.com/', ''), 'https://example.com/');
  assert.equal(buildSitemap([{ path: '/x/' }], 'https://example.com/').includes(
    '<loc>https://example.com/x/</loc>'
  ), true);
});

test('buildSitemap handles empty page list', () => {
  const xml = buildSitemap([], 'https://example.com');
  const doc = parser.parse(xml);
  assert.equal(doc.urlset['@_xmlns'], 'http://www.sitemaps.org/schemas/sitemap/0.9');
  assert.equal(doc.urlset.url, undefined);
});

test('buildRobots emits exact robots.txt output', () => {
  assert.equal(
    buildRobots({
      sitemapUrl: 'https://example.com/sitemap.xml',
      disallow: ['/admin/', '/private/'],
    }),
    'User-agent: *\nDisallow: /admin/\nDisallow: /private/\nSitemap: https://example.com/sitemap.xml\n'
  );

  // Empty disallow list -> single "Disallow:" (allow all)
  assert.equal(
    buildRobots({ sitemapUrl: 'https://example.com/sitemap.xml' }),
    'User-agent: *\nDisallow:\nSitemap: https://example.com/sitemap.xml\n'
  );
});

