'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { buildSitemap, buildRobots } = require('../src/index.js');

const ORIGIN = process.env.SITE_ORIGIN || 'https://example.com';

const pages = [
  { path: '/', lastmod: '2026-08-01', changefreq: 'weekly', priority: 1 },
  { path: '/about', lastmod: '2026-07-12', changefreq: 'monthly', priority: 0.8 },
  { path: '/blog', lastmod: '2026-08-20', changefreq: 'daily', priority: 0.7 },
  { path: '/search?lang=en&topic=seo', lastmod: '2026-06-30', changefreq: 'monthly', priority: 0.5 },
];

const dist = path.join(__dirname, '..', 'dist');
fs.mkdirSync(dist, { recursive: true });

const sitemapUrl = `${ORIGIN.replace(/\/+$/, '')}/sitemap.xml`;

fs.writeFileSync(path.join(dist, 'sitemap.xml'), buildSitemap(pages, ORIGIN));
fs.writeFileSync(
  path.join(dist, 'robots.txt'),
  buildRobots({ sitemapUrl, disallow: ['/admin/'] })
);

console.log(`Wrote ${dist}/sitemap.xml and ${dist}/robots.txt for ${ORIGIN}`);

